import {createClient} from 'https://esm.sh/@supabase/supabase-js@2.49.1';
import {supabaseUrl,supabasePublishableKey} from './supabase-config.js';

const supabase=createClient(supabaseUrl,supabasePublishableKey),$=id=>document.getElementById(id);
const managers=new Set(['nikkhaikal@gmail.com','nealia.najihah@gmail.com']);
const dashboardRows=['Keyin','Net','Recruitment:','NAHP','AHP','Total HP','T/O','SHI Group','SHI Personal','WS Player','Target Collection','Actual Collection'];
const hpRows=['Keyin','Net','Recruitment:','NAHP','AHP','Total HP','T/O','SHI Personal','WS Player','Target Collection','Actual Collection'];
let months=[...Array(6)].map((_,i)=>({label:['December','January','February','March','April','May'][i],key:`month-${2026+(i>0?1:0)}-${String(i===0?12:i).padStart(2,'0')}`}));
const totals=[['Recruitment','Recruitment:'],['NAHP','NAHP'],['AHP','AHP'],['Total HP','Total HP'],['Key in','Keyin'],['Net','Net']];
let dashboard={},hps=new Map(),selectedCode='',user=null,profile=null,canManage=false,canEditHp=false,saveTimer,refreshTimer;
function message(id,value='',kind=''){const el=$(id);el.textContent=value;el.className=`message ${kind}`}
function number(value){const n=Number(String(value??'').replaceAll(',','').trim());return Number.isFinite(n)?n:0}
function shi(actual,target){return target>0?`${(actual/target*100).toFixed(1)}%`:'—'}
function collections(values,prefix,labels){return{target:number(values[`${prefix}-${labels.indexOf('Target Collection')}-target`]),actual:number(values[`${prefix}-${labels.indexOf('Actual Collection')}-actual`])}}
function groupShi(){let target=0,actual=0;for(const hp of hps.values()){const amount=collections(hp.metrics,'hp',hpRows);target+=amount.target;actual+=amount.actual}return shi(actual,target)}
function makeCell(text,key,editable,save){const td=document.createElement('td');td.textContent=text;td.contentEditable=editable?'true':'false';if(editable)td.addEventListener('blur',()=>save(key,td.textContent.trim()));return td}
function table(target,labels,values,prefix,editable,save){const body=$(target),amount=collections(values,prefix,labels);body.replaceChildren();labels.forEach((name,i)=>{const tr=document.createElement('tr'),calculated=name==='SHI Personal'||name==='SHI Group';for(const [field,fallback] of [['label',name],['target','—'],['actual','—']]){const key=`${prefix}-${i}-${field}`,allowed=!calculated&&!(name==='Target Collection'&&field!=='target')&&!(name==='Actual Collection'&&field!=='actual');let value=values[key]??fallback;if(calculated)value=field==='label'?name:field==='actual'?(name==='SHI Group'?groupShi():shi(amount.actual,amount.target)):'—';if(name==='Target Collection'&&field==='actual'||name==='Actual Collection'&&field==='target')value='—';tr.append(makeCell(value,key,editable&&allowed,save))}body.append(tr)})}
async function saveDashboard(key,value){dashboard[key]=value;renderDashboard();clearTimeout(saveTimer);saveTimer=setTimeout(async()=>{const{error}=await supabase.from('dashboards').update({values:dashboard}).eq('id','main');if(error)message('authMessage',error.message,'error')},350)}
async function saveHp(key,value){if(!selectedCode||!canEditHp)return;const current=hps.get(selectedCode);if(!current)return;const metrics={...current.metrics,[key]:value};const{error}=await supabase.from('hps').update({metrics}).eq('code',selectedCode);if(error)message('hpMessage',error.message,'error');else{current.metrics=metrics;renderScoreboard();renderDashboard();renderHp()}}
function renderDashboard(){table('scoreTable',dashboardRows,dashboard,'score',canManage,saveDashboard);$('monthlyPlan').replaceChildren();months.forEach((month,i)=>{const box=document.createElement('div'),label=document.createElement('b'),content=document.createElement('span');box.className='month';label.textContent=month.label;content.textContent=dashboard[month.key]??dashboard[`month-${i}`]??'Add monthly focus';content.contentEditable=canManage?'true':'false';content.dataset.editable=String(canManage);if(canManage)content.addEventListener('blur',()=>saveDashboard(month.key,content.textContent.trim()));box.append(label,content);$('monthlyPlan').append(box)});$('editStatus').textContent=canManage?'Editing enabled':'View only'}
function renderScoreboard(){const board=$('scoreboard');board.replaceChildren();for(const [title,rowName] of totals){const i=hpRows.indexOf(rowName),sum=[...hps.values()].reduce((total,hp)=>total+number(hp.metrics[`hp-${i}-actual`]),0),card=document.createElement('div'),label=document.createElement('small'),value=document.createElement('strong');card.className='stat';label.textContent=`Total ${title}`;value.textContent=new Intl.NumberFormat('en-MY',{maximumFractionDigits:2}).format(sum);card.append(label,value);board.append(card)}}
function renderHpSelect(){const select=$('hpSelect'),previous=selectedCode;select.replaceChildren();if(!hps.size){select.add(new Option('No HP accounts yet',''));selectedCode=''}else{for(const [code,hp] of [...hps].sort((a,b)=>a[0].localeCompare(b[0])))select.add(new Option(`${code} · ${hp.name}`,code));selectedCode=hps.has(previous)?previous:select.options[0].value;select.value=selectedCode}renderHp()}
function renderHp(){const hp=hps.get(selectedCode);canEditHp=!!user&&(canManage||hp?.uid===user.id||hp?.parent_uid===user.id);$('hpIdentity').textContent=hp?`${selectedCode} · ${hp.name}`:'Register the first HP to start tracking.';table('hpTable',hpRows,hp?.metrics||{},'hp',canEditHp,saveHp)}
async function refresh(){if(!user)return;const [d,h]=await Promise.all([supabase.from('dashboards').select('values').eq('id','main').single(),supabase.from('hps').select('code,uid,parent_uid,name,email,metrics')]);if(d.error)message('authMessage',d.error.message,'error');else dashboard=d.data.values||{};if(h.error)message('hpMessage',h.error.message,'error');else hps=new Map(h.data.map(hp=>[hp.code,hp]));renderDashboard();renderHpSelect();renderScoreboard()}
function loginEmail(username){const value=username.trim().toLowerCase();if(value==='admin')return 'nikkhaikal@gmail.com';if(value==='jiha')return 'nealia.najihah@gmail.com';if(/^[a-z0-9-]{2,24}$/.test(value))return `${value}@users.jihadashboard.invalid`;return ''}
async function accountRequest(action,details={}){const {data}=await supabase.auth.getSession();const response=await fetch('/.netlify/functions/accounts',{method:'POST',headers:{'content-type':'application/json',Authorization:`Bearer ${data.session?.access_token||''}`},body:JSON.stringify({action,...details})});const result=await response.json();if(!response.ok)throw new Error(result.error||'Account request failed');return result}
async function loadAdminUsers(){if(!user||user.email?.toLowerCase()!=='nikkhaikal@gmail.com')return;try{const {users}=await accountRequest('list'),box=$('userList');box.replaceChildren();if(!users.length){box.textContent='No HP logins yet.';return}for(const item of users){const row=document.createElement('div'),label=document.createElement('span'),input=document.createElement('input'),reset=document.createElement('button'),remove=document.createElement('button');row.className='controls';label.textContent=`${item.username} · ${item.name} · Last sign-in: ${item.last_sign_in_at?new Date(item.last_sign_in_at).toLocaleDateString():'Never'}`;input.type='password';input.placeholder='New password (12+ characters)';input.autocomplete='new-password';reset.textContent='Set password';reset.addEventListener('click',async()=>{try{await accountRequest('password',{userId:item.id,password:input.value});input.value='';message('adminMessage',`Password changed for ${item.username}.`,'success')}catch(error){message('adminMessage',error.message,'error')}});remove.textContent='Delete inactive login';remove.className='ghost';const inactive=!item.last_sign_in_at||Date.now()-new Date(item.last_sign_in_at).getTime()>=90*86400000;remove.disabled=!inactive||!item.can_delete;remove.addEventListener('click',async()=>{if(!confirm(`Delete ${item.username}'s login? Their HP results will stay in reports.`))return;try{await accountRequest('delete',{userId:item.id});message('adminMessage',`Login ${item.username} deleted.`,'success');await loadAdminUsers();await refresh()}catch(error){message('adminMessage',error.message,'error')}});row.append(label,input,reset,remove);box.append(row)}}catch(error){message('adminMessage',error.message,'error')}}
function setTimeline(start,end){const first=new Date(`${start.slice(0,7)}-01T00:00:00Z`),last=new Date(`${end.slice(0,7)}-01T00:00:00Z`),list=[];for(let date=new Date(first),i=0;date<=last&&i<25;date.setUTCMonth(date.getUTCMonth()+1),i++){const key=`month-${date.toISOString().slice(0,7)}`;list.push({key,label:new Intl.DateTimeFormat('en-GB',{month:'long',year:'numeric',timeZone:'UTC'}).format(date)})}months=list;$('timelineLabel').textContent=`${months[0]?.label||''} to ${months.at(-1)?.label||''}`;renderDashboard()}
async function loadReports(){if(!user)return;const [settings,history]=await Promise.all([supabase.from('report_settings').select('period_start,period_end,timeline_start,timeline_end').eq('id','main').single(),supabase.from('monthly_reports').select('id,period_start,period_end,dashboard_values,hp_values').order('period_end',{ascending:false})]);if(settings.error){message('reportMessage',settings.error.message,'error');return}$('periodEnd').value=settings.data.period_end;$('periodEnd').min=settings.data.period_start;$('timelineStart').value=settings.data.timeline_start;$('timelineEnd').value=settings.data.timeline_end;setTimeline(settings.data.timeline_start,settings.data.timeline_end);window.reportHistory=history.data||[];const box=$('reportHistory');box.replaceChildren();for(const report of window.reportHistory){const line=document.createElement('p');line.textContent=`${report.period_start} to ${report.period_end} · ${report.hp_values?.length||0} HPs`;box.append(line)}}
async function signedIn(current){user=current;canManage=!!current&&managers.has((current.email||'').toLowerCase());profile=null;clearInterval(refreshTimer);if(current){const{data,error}=await supabase.from('profiles').select('hp_code').eq('id',current.id).maybeSingle();if(error)message('authMessage',error.message,'error');profile=data}$('login').classList.toggle('hidden',!!current);$('session').classList.toggle('hidden',!current);$('accounts').classList.toggle('hidden',!canManage);$('adminControls').classList.toggle('hidden',current?.email?.toLowerCase()!=='nikkhaikal@gmail.com');$('reports').classList.toggle('hidden',!current);$('periodEnd').disabled=!canManage;$('savePeriodEnd').disabled=!canManage;$('timelineStart').disabled=!canManage;$('timelineEnd').disabled=!canManage;$('saveTimeline').disabled=!canManage;$('userLabel').textContent=current?`${canManage?(current.email.toLowerCase()==='nikkhaikal@gmail.com'?'admin':'jiha'):profile?.hp_code||'HP'} · ${canManage?'Team manager':profile?.hp_code||'Awaiting HP'}`:'';if(current&&(canManage||profile?.hp_code)){if(canManage){const result=await supabase.rpc('close_due_month');if(result.error)message('reportMessage',result.error.message,'error')}await refresh();await loadReports();if(current.email?.toLowerCase()==='nikkhaikal@gmail.com')await loadAdminUsers();refreshTimer=setInterval(refresh,15000)}else{dashboard={};hps.clear();selectedCode='';renderDashboard();renderHpSelect();renderScoreboard();message('authMessage',current?'Ask an admin to link your HP code.':'Sign in to see Jiha’s team.')}}
$('hpSelect').addEventListener('change',e=>{selectedCode=e.target.value;renderHp()});
$('signIn').addEventListener('click',async()=>{const email=loginEmail($('email').value),password=$('password').value;if(!email){message('authMessage','Enter admin, jiha or your HP code.','error');return}const{error}=await supabase.auth.signInWithPassword({email,password});message('authMessage',error?'Sign in failed. Check your username and password.':'',error?'error':'')});
$('signOut').addEventListener('click',()=>supabase.auth.signOut());
$('createAccount').addEventListener('click',async()=>{const code=$('newCode').value.trim().toUpperCase(),name=$('newName').value.trim(),password=$('newPassword').value;const button=$('createAccount');button.disabled=true;try{await accountRequest('create',{code,name,password});message('accountMessage',`HP ${code} created. Give them their username and password privately.`,'success');$('newCode').value=$('newName').value=$('newPassword').value='';await refresh();if(user.email?.toLowerCase()==='nikkhaikal@gmail.com')await loadAdminUsers()}catch(error){message('accountMessage',error.message,'error')}button.disabled=false});
$('saveTimeline').addEventListener('click',async()=>{const start=$('timelineStart').value,end=$('timelineEnd').value;if(!start||!end||end<start){message('reportMessage','Choose a valid timeline start and end.','error');return}const{error}=await supabase.from('report_settings').update({timeline_start:start,timeline_end:end}).eq('id','main');if(error)message('reportMessage',error.message,'error');else{setTimeline(start,end);message('reportMessage','Timeline saved.','success')}});
$('savePeriodEnd').addEventListener('click',async()=>{const date=$('periodEnd').value;if(!date){message('reportMessage','Choose an end date.','error');return}const{error}=await supabase.from('report_settings').update({period_end:date,closing_day:Number(date.slice(-2))}).eq('id','main');message('reportMessage',error?error.message:'Month-end date saved.',error?'error':'success')});
function csvCell(v){return `"${String(v??'').replaceAll('"','""')}"`}
function reportRows(){const lines=[['Period','HP code','HP name','Row','Target','Actual']];function add(period,values,code,name,prefix,labels){labels.forEach((label,i)=>lines.push([period,code,name,values[`${prefix}-${i}-label`]||label,values[`${prefix}-${i}-target`]||'',values[`${prefix}-${i}-actual`]||'']))}add('Current',dashboard,'','Team dashboard','score',dashboardRows);for(const [code,hp] of hps)add('Current',hp.metrics,code,hp.name,'hp',hpRows);for(const report of window.reportHistory||[]){add(report.period_end,report.dashboard_values,'','Team dashboard','score',dashboardRows);for(const hp of report.hp_values||[])add(report.period_end,hp.metrics,hp.code,hp.name,'hp',hpRows)}return lines}
$('downloadReport').addEventListener('click',()=>{const csv=reportRows().map(row=>row.map(csvCell).join(',')).join('\r\n'),link=document.createElement('a');link.href=URL.createObjectURL(new Blob(['\ufeff',csv],{type:'text/csv;charset=utf-8'}));link.download='jiha-team-report.csv';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000)});
$('printReport').addEventListener('click',()=>{const section=$('printData'),heading=document.createElement('h1'),table=document.createElement('table');heading.textContent='Jiha Team Report';section.replaceChildren(heading);for(const [index,row] of reportRows().entries()){const tr=document.createElement('tr');for(const value of row){const cell=document.createElement(index?'td':'th');cell.textContent=value;tr.append(cell)}table.append(tr)}section.append(table);window.print()});
supabase.auth.onAuthStateChange((event,session)=>{if(event==='SIGNED_IN'||event==='SIGNED_OUT'||event==='INITIAL_SESSION')setTimeout(()=>signedIn(session?.user||null),0)});
$('today').textContent=new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'long',year:'numeric'}).format(new Date());renderDashboard();renderHpSelect();renderScoreboard();
